#!/usr/bin/env python3
"""Reproduce Unicode 17 grapheme tables from the pinned, licensed vendor data."""
from pathlib import Path
import argparse
root = Path(__file__).resolve().parents[1]
source = root / 'vendor/unicode'
properties = ['Other', 'CR', 'LF', 'Control', 'Extend', 'ZWJ', 'Regional_Indicator',
              'Prepend', 'SpacingMark', 'L', 'V', 'T', 'LV', 'LVT']
def ranges(file, select):
    result = []
    for line in (source / file).read_text().splitlines():
        fields = [x.strip() for x in line.split('#')[0].split(';')]
        if len(fields) < 2:
            continue
        value = select(fields[1:])
        if not value:
            continue
        bounds = fields[0].split('..')
        result.append((int(bounds[0], 16), int(bounds[-1], 16), value))
    return sorted(result)
def table(name, values):
    return 'static const unsigned char ' + name + '[] = {\n' + ''.join(
        '    ' + ','.join(str(v) for v in values[i:i+32]) + ',\n'
        for i in range(0, len(values), 32)) + '};\n'
text = '/* Generated by scripts/unicode-tables.py. Unicode 17.0.0.\n * Copyright Unicode, Inc. See vendor/unicode/LICENSE.txt. */\n'
text += 'enum { ' + ', '.join('G_' + x.upper() for x in properties) + ' };\n'
# One byte combines GCB (4 bits), InCB (2), pictographic and presentation.
# Intern equal 128-scalar pages: two indexed loads replace binary searches,
# including the many disjoint Hangul syllable ranges. No runtime initialization.
data = bytearray(0x110000)
for rows, shift in (
    (ranges('GraphemeBreakProperty.txt', lambda p: properties.index(p[0])), 0),
    (ranges('DerivedCoreProperties.txt', lambda p:
        {'Consonant': 1, 'Linker': 2, 'Extend': 3}.get(p[1], 0) if p[0] == 'InCB' else 0), 4),
    (ranges('emoji-data.txt', lambda p: int(p[0] == 'Extended_Pictographic')), 6),
    (ranges('emoji-data.txt', lambda p: int(p[0] == 'Emoji_Presentation')), 7),
):
    for a, b, value in rows:
        for cp in range(a, b+1):
            data[cp] |= value << shift
pages, indices = {}, []
for offset in range(0, len(data), 128):
    page = bytes(data[offset:offset+128])
    indices.append(pages.setdefault(page, len(pages)))
assert len(pages) <= 256, 'page indices no longer fit in one byte'
text += table('unicode_pages', indices)
text += table('unicode_properties', b''.join(pages))
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check', action='store_true')
if parser.parse_args().check:
    if (root / 'src/grapheme_data.h').read_text() != text:
        parser.exit(1, 'grapheme_data.h is stale; run scripts/unicode-tables.py\n')
else:
    (root / 'src/grapheme_data.h').write_text(text)
